// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E101_E150 = Object.freeze({"E101.1":{"s":"Mair takes off Margarita's red blanket and hands her a leash, as if handing over a fortress. The goat immediately eats the edge of the travel bag, but leaves food supplies for the squad."},"E101.2":{"s":"Affected gardeners receive compensation, and Mair stamps the complaints as “settled.” Margarita immediately heads to the fourth garden."},"E101.3":{"s":"{{heroName}} finds a loophole in the decree: Margarita’s dignity is inviolable, but bills for cabbage are not state. Delighted peasants return part of the previously withheld money to the treasury.","f":"{{heroName}} reads out the clarification, but Mair presents a certified copy of the decree with even worse wording. The village is charging legal costs for the attempted review."},"E101.4":{"s":"The headman records Margarita as the only debtor on her own accounts. The goat bleats, but no one else demands money from the king's purse.","f":"When trying to collect a debt from a goat, its defenders declare this an insult to the throne. A skirmish begins in the square."},"E101.5":{"s":"You leave Meir to deal with the royal goat according to local laws. The last thing heard across the bridge is a demand to pay for another cabbage bush."},"E102.1":{"s":"The first bailiff accepts the girl upon receipt and presents the reward stipulated by the order. She takes the box with her without saying goodbye.","f":"The first bailiff reaches for the box, but the girl retreats and demands to see the second order. The transfer is disrupted, and the squad is left without a reward."},"E102.2":{"s":"The second bailiff takes the girl under guard and gives her supplies for the road. Finally, she clutches the closed box tighter to herself.","f":"The first bailiff blocks the opponent's path, declaring a violation of the royal order. The dispute turns into a clash."},"E102.3":{"s":"{{heroName}} matches the signatures and finds a record of the replacement of the order in transit. For exposing the substitution, the squad receives gold, and the girl is handed over according to a valid order.","f":"{{heroName}} only proves that both orders are genuine; It is not possible to determine which of them should operate. The girl is left with the box under the supervision of the arguing bailiffs."},"E102.4":{"s":"You sit the girl next to the driver and promise to take her to the nearest city without bailiffs. An additional passenger costs supplies."},"E102.5":{"s":"The box contains a certificate with the seals of both departments and a hidden wallet. The gold found goes into the treasury, and the girl silently slams the lid.","f":"The girl manages to scream when you rip off the lid, and both bailiffs accuse the squad of stealing evidence. A skirmish begins."},"E103.1":{"s":"The king acknowledges the long-standing will of the land, and the talking stone falls silent for the first time with obvious satisfaction. Rudek thanks the squad with bags of fresh harvest."},"E103.2":{"s":"Gaston receives legal confirmation of the transaction and calculates the decision fee. The stone by the road scrapes discontentedly along the pavement, but the boundaries remain on paper."},"E103.3":{"s":"The spirit agrees to move the boundary to the old stream, leaving Rudek part of the arable land. Gaston pays for the completed transaction and shares the travel supplies.","f":"At the proposed new border, the pillars are back to their old state overnight. Stone refuses to discuss other areas."},"E103.4":{"s":"You dig up the stone, and Gaston pays for the witness. He grumbles all the way that the move must also be formalized by law.","f":"As soon as the shovels touch the stone, its defenders rise from the ground. Instead of a trial, a fight breaks out."},"E103.5":{"s":"You leave Gaston, Rudek and the talking stone to argue over ownership. Behind you there is a demand to invite a notary who knows how to listen to the land."},"E104.1":{"s":"You help Oswald line the edges of the grave and share dinner with him. The old man thanks him for the work with gold and promises not to go there early."},"E104.2":{"s":"Oswald puts down the shovel: his oath to his comrade can be fulfilled later. He takes the sword and goes with your squad.","f":"Oswald refuses to go, but gets provisions for the road from old supplies. “It’s too early to bury, but it’s time to feed guests,” he says.","v":{"rs":"Oswald is ready to take the sword, but he cannot accept a new fighter. The old man hands over the gold and returns to his grave."}},"E104.3":{"s":"{{heroName}} listens to Timo alone, and he finally decides to argue with his uncle not about the grave, but about tomorrow. In gratitude, the nephew gives away travel supplies.","f":"{{heroName}} tries to get Timo to talk, but he replies that he has already told his uncle everything he needs to know. The squad leaves without gifts."},"E104.4":{"s":"The priest marks a place for Oswald in the cemetery register and accepts payment. The old man looks happy: now he can move on with his life in peace."},"E104.5":{"s":"You are not interfering with a promise made twenty years ago. Oswald continues to dig, and Timo sits next to him, his hands folded defiantly."},"E105.1":{"s":"You dismantle a piece of the wall where a knock is heard from inside, and open a passage to the tavern. Helm gives the promised dinner and supplies.","f":"The very first stones fall inside, and you have to stop so as not to hit the visitors. Supplies are wasted on useless work."},"E105.2":{"s":"You find a hidden pattern on the wall and remove the spell that hid the opening. Helm thanks for the rescue with the proceeds from the cash register.","f":"When you touch the pattern, the wall responds and {{affectedHeroName}} is severely injured. The entrance never appears.","v":{"nf":"The enchantment on the wall works, but no one among the available fighters is seriously injured. The opening remains invisible."}},"E105.3":{"s":"{{heroName}} finds a safe point in the masonry, and instead of the third blow, an opening opens in the wall. The innkeeper gives out gold and a traveling dinner.","f":"{{heroName}} discovers that rebuilding the wall is now dangerous: there are load-bearing beams behind it. The squad still doesn’t open the entrance."},"E105.4":{"s":"The guests take turns climbing out of the windows, and Helm is the last to push out a bag of food in gratitude. The knocking comes from inside again, but there is no one left to spend the night there."},"E105.5":{"s":"In the morning, an ordinary door is discovered in the wall, as if it had never disappeared. Helm grabs her hand before she can change her mind.","f":"At night, armed creatures emerge from a blank wall, whom the tavern visitors have not seen. The squad has to start a skirmish."},"E106.1":{"s":"The king announces one contest instead of twenty-seven separate courtships, and the bridge is finally cleared. Secretary Ed pays for the organization in gold.","f":"The losing suitors accuse the judges of bias and block the road with shields. A skirmish begins."},"E106.2":{"s":"Lissa thanks for the idea that the absence of a groom could also be a solution, and opens the driveway. The squad receives supplies for the path.","f":"Lissa takes the advice for a public insult and demands compensation for disrupting the show. The squad has to give up the gold."},"E106.3":{"s":"{{heroName}} tells each groom to decide for himself what to do with his own queue. Most leave immediately, and Ed pays for the freed bridge.","f":"{{heroName}} proposes a test, but the contenders begin to argue about the rules before it even begins. The road remains lined with carts."},"E106.4":{"s":"One of the suitors decides that a hike is the best place to make decisions on their own, and enrolls in your party.","f":"The most intelligent applicant politely refuses: he came to get married, and not to enroll in the squad.","v":{"rs":"The groom would willingly change the tournament to a campaign, but it is impossible to take a new fighter. Instead of serving, he thanks the detachment with gold."}},"E106.5":{"s":"You turn towards the ford, using up supplies on the long detour. Behind you, twenty-seven voices simultaneously ask which horse is better."},"E107.1":{"s":"The king opens the envelope and finds a list of old travel caches. According to one of the clues, the squad obtains supplies.","f":"The paper burns the King's palms before he can read the first line. He is seriously injured.","v":{"nf":"The seal of the letter flashes in the King's hands, but no serious injury occurs. The content remains unparsed."}},"E107.2":{"s":"You set the envelope on fire and the old gold coins hidden in the seal fall out of the ashes. Ylwe doesn't try to stop you.","f":"Fire does not take paper; Instead, armed guardians of the letter appear near the pavilion. A skirmish begins."},"E107.3":{"s":"{{heroName}} breaks the connection between the seal and the reader without opening the envelope. Ylwe pays in gold for freedom from many years of danger.","f":"{{heroName}} sees that the spell is hooked to every word of the letter, and does not risk breaking them blindly. The envelope remains sealed."},"E107.4":{"s":"You leave the letter on the table where it has lain for one hundred and ninety years. Ylwe locks the pavilion again and turns off the lights."},"E108.1":{"s":"You're checking cutting marks and confiscation records, not Aer's choices. The parties accept the findings and the merchant pays for the proceedings.","f":"Witnesses contradict each other, and foresters do not provide an inventory of the trees. The court returns to the deer without a decision."},"E108.2":{"s":"Aer goes for apples to the chosen tablet, and the arguing elves take this as a verdict. For your service you receive gold.","f":"The deer eats the apples along with the plank and remains in place. Supplies have been spent and no decision has been made."},"E108.3":{"s":"Traces of living magic are found in the wood, confirming the violation of the ban. Forest rangers give away supplies for help in the investigation.","f":"The test spoils some of the samples and uses up supplies, but does not show anything definitive. The charges remain the same."},"E108.4":{"s":"You announce that Aer, through his silence, offers peace, and the parties divide the disputed cargo by agreement. For mediation you are paid in gold.","f":"The trader demands a written verdict, and the forest rangers expect at least one step from the deer. The settlement agreement does not work out."},"E108.5":{"s":"You leave the two elves to wait for Aer's decision. The deer is already chewing on the corner of the last plank."},"E109.1":{"s":"You find the words that Maerin has been trying to remember for a long time, and the beech opens an old hollow. Inside is gold left by her mother.","f":"The last line comes out wrong, and the roots tighten their grip on the old chest. Maerin asks not to sing at random anymore."},"E109.2":{"s":"You cut dry roots and remove the chest from the hollow. The gold goes to the treasury, although Maerin is not happy about this decision.","f":"The beech raises its roots around the axes, and its defenders come from the forest. A skirmish begins."},"E109.3":{"s":"{{heroName}} reads the remains of the melody from the memory of the beech, and Maerin finishes singing it in its entirety for the first time. The tree opens a chest containing gold and travel supplies.","f":"{{heroName}} distinguishes only the first bars of a forgotten song; the tree does not respond to attempts to restore the end. The chest remains closed."},"E109.4":{"s":"Maerin agrees that the unfinished song also preserves the memory of her mother. She shares supplies with the squad and stays by the tree.","f":"Maerin asks not to deprive her of her last hope of hearing the song in full. You leave without a gift."},"E109.5":{"s":"You leave Maerin alone with the beech and the unsung melody. For a long time you can hear the branches repeating the broken line."},"E110.1":{"s":"You choose the old road without a single comment about the new one. The trail goes a long way, so some of the supplies are spent on the transition."},"E110.2":{"s":"You praise the path, and it leads the party to a short passage with a supply of food left by the travelers. There are more supplies.","f":"The path hears praise, but does not change direction one step. There is no shortcut and no reward."},"E110.3":{"s":"{{heroName}} rushes forward, and the path noisily changes to fast speed. At an unexpected turn, the party finds gold.","f":"The path bends sharply under the rider's feet, and {{affectedHeroName}} is seriously injured.","v":{"nf":"The path changes direction too abruptly, but among the available fighters no one is seriously wounded. There is no promised shortcut."}},"E110.4":{"s":"You cut your own clearing and go out to the road, not paying attention to the disgruntled rustling behind you.","f":"While you are clearing a clearing, the forest puts up armed defenders of someone else’s path. A skirmish begins."},"E110.5":{"s":"You return to the fork and take another route. Eren asks not to look back when the old path begins to rustle."},"E111.1":{"s":"The detachment follows the whistle and finds an abandoned hunting camp with intact supplies. Ciel recognizes his brother's arrows, but he himself is not among the trees.","f":"The whistle is heard from all sides, and the thicket closes around the fighters. Armed forest hunters come out of their hiding places and the battle begins."},"E111.2":{"s":"The fire drives out of the thickets those who were hiding near the old hunters' hiding place. Without engaging in battle, the squad takes the left gold.","f":"It is not Ciel’s missing comrades who respond to the smoke, but the armed owners of the thicket. A skirmish begins at the fire."},"E111.3":{"s":"{{heroName}} inspects the upper branches and discovers a hidden rest stop with supplies. The hunters' tracks end there, but they manage to take the reserve.","f":"An old loop is triggered between the branches, and {{affectedHeroName}} is seriously injured. The search has to be stopped.","v":{"nf":"A trap in the crowns disrupts reconnaissance, but none of the eligible fighters are seriously injured. The trail of the missing is lost."}},"E111.4":{"s":"Ciel agrees not to send new people after his brother without preparation. She thanks the party with gold and removes one of the empty quivers from the wall.","f":"Ciel refuses to leave: she hears the familiar whistle again and grabs the bow. She fails to convince her."},"E111.5":{"s":"You leave Ciel at the hanging bows. The whistle from the forest is repeated, but the detachment is already on the road."},"E112.1":{"s":"Finn takes out a hidden letter with the will of the mistress, and the heirs finally see her decision about the division. For the restored will, the detachment is paid gold.","f":"Finn is frightened by the threats and declares that the letter is lost. The heirs are demanding compensation from you for fruitless proceedings."},"E112.2":{"s":"You acknowledge all three branches as a sign of the mother's will, and the heirs agree to divide the land. Finn supplies the party with supplies in gratitude.","f":"Two heirs accuse the third of bribing the gardener and take up arms. A skirmish begins."},"E112.3":{"s":"{{heroName}} invites each heir to declare his share as independent ownership. No one has to admit defeat, and the squad is paid in gold and provisions.","f":"{{heroName}} offers conditions, but the heirs argue about seniority even with an equal division. The contract has not been concluded."},"E112.4":{"s":"The next morning, the young tree again extends three branches towards the disputants. The heirs recognize the sign and give gold in gratitude.","f":"During the night, the branches intertwine so that no one can point to theirs. The family dispute continues without resolution."},"E112.5":{"s":"You refuse to decide the fate of someone else's estate without sufficient grounds. Finn remains between the heirs and the tree with three branches."},"E113.1":{"s":"Brag and his comrades carry out their assigned work with unexpected diligence. For repairing the crossing, they leave the collected supplies to the detachment."},"E113.2":{"s":"The leader takes five “prisoners” and pays in gold, no questions asked. Brag looks longingly at the road back to the camp.","f":"Brag understands where he is being led and rouses his comrades to resist. A skirmish begins."},"E113.3":{"s":"Brag is the first to volunteer to serve the King if it will save him from cesspools. One of the orcs joins the squad.","f":"The orcs decide that the campaign is too similar to serving the leader, and refuse. As an apology, they leave some provisions.","v":{"rs":"Brag agrees to serve, but he cannot accept a new fighter. The orcs thank you for the offer with gold and leave to look for another way to avoid punishment."}},"E113.4":{"s":"You propose to the leader that the punishment be replaced with a real test for the five fighters. The orcs roar in approval and pay gold for advice.","f":"Brag and his friends reject every challenge that requires them to work. It is impossible to persuade them."},"E113.5":{"s":"You return Braga his ax and tell the five to immediately go to the leader. The orcs line up so dejectedly, as if they can already hear the sound of shovels."},"E114.1":{"s":"The king beats the drum, and real rain finally falls over the camp. Grateful orcs supply the squad with provisions.","f":"After the beat of the drum, armed uninvited guests appear instead of rain. Urkh hides his sticks: the battle begins."},"E114.2":{"s":"You explain to Urhu how to find underground water and dig a well without any spells. The shaman pays gold for an idea.","f":"Urkh listens carefully to the advice and asks who will dig. This concludes the discussion of the well."},"E114.3":{"s":"{{heroName}} swaps the wrong runes, and the drum causes normal rain. Urkh rewards the squad with gold and supplies.","f":"{{heroName}} tries to restore the runes, but the drum absorbs the prepared materials. Supplies are becoming scarcer and there is no rain."},"E114.4":{"s":"You pay for the drum, and Urkh hands it over without making any promises about the weather. The orcs look suspiciously happy with the deal."},"E114.5":{"s":"You leave the orc camp while Urkh puts the skin back on the drum. Following this there is a sound surprisingly similar to an official cough."},"E115.1":{"s":"You give Garra the gold for the knocked out tooth, and she solemnly declares Peak's debt closed. The young orc closes his mouth for the first time that day."},"E115.2":{"s":"The fight ends with the first scratch, and Garra accepts the outcome as fair compensation. For the arranged trial you are given gold.","f":"A training dispute turns into a real blow: {{affectedHeroName}} is seriously injured. The custom turns out to be much more dangerous than the tooth.","v":{"nf":"The fight breaks down before any eligible combatants are seriously wounded. Garra is still seeking compensation."}},"E115.3":{"s":"{{heroName}} offers Piku to make up for the grudge by working for Garra, without humiliating either of them. The orcs agree and supply the squad with supplies.","f":"{{heroName}} offers reconciliation, but Garra demands to hear an apology from Pieck first. The dispute remains open."},"E115.4":{"s":"Pieck decides to work off his duty by serving away from the training site and joins the squad.","f":"Garra does not agree to consider someone else’s service as payment for her tooth. Pieck remains by the fire and continues the argument.","v":{"rs":"Peak is ready to go on a campaign, but there is no room for a new fighter. Instead of service, the orcs give the squad a small monetary thank you."}},"E115.5":{"s":"You leave Garra and Pieck to argue about the fair price of one tooth. By the time you left, the offer had already increased to three."},"E116.1":{"s":"You explain to the young orc what name Oma heard and invite him to decide for himself. He places his palm on the stone again, no longer hiding his trembling.","f":"The teenager takes the story as an attempt to humiliate him in front of the clan and leaves the stone. Oma never completes the ritual."},"E116.2":{"s":"You call a neutral name, and Oma completes the ritual without revealing the stone's whisper. The grateful elder hands over the gold.","f":"The stone repeats the forbidden name out loud, exposing the substitution. Supplies are being wasted trying to calm the crowd."},"E116.3":{"s":"{{heroName}} separates the ancient echo of the stone from the living voice of a teenager. Oma performs the ritual again and rewards the party with supplies.","f":"{{heroName}} cannot understand whether the whisper belongs to the stone or the memory of the elder. Oma postpones the ceremony."},"E116.4":{"s":"You break the black stone and find old gold plates inside. For the first time, a teenager hears silence instead of someone else's name.","f":"Hitting the stone raises the clan's guardians, who consider the destruction a sacrilege. The battle begins."},"E116.5":{"s":"You leave Omu and the teenager in front of the Name Stone. The elder once again leans towards its surface, but does not say a word."},"E117.1":{"s":"You address Fang as captain, and the wolf importantly lets the squad through to the river. Turg thanks you with supplies because no one challenged the charter.","f":"Fang refuses to accept other people's negotiations and leads the patrol after a suspicious squirrel. You do not receive any agreed passage or reward."},"E117.2":{"s":"The wolf agrees to exchange the captain's badge for meat, and Turg regains command. He pays in gold for the saved position."},"E117.3":{"s":"{{heroName}} descends to the level of the wolf's eyes and with gestures convinces Fang to let the squad through. Turg issues supplies while the captain is busy with a new trail.","f":"{{heroName}} misunderstands the short growl and receives in response only a demand not to approach the box. The agreement did not take place."},"E117.4":{"s":"You hold Fang's gaze longer than he holds yours. Turg declares a legitimate victory and thanks him with gold.","f":"Fang suddenly lunges at the game participant, and {{affectedHeroName}} is seriously injured. The patrol still obeys the wolf.","v":{"nf":"The game ends with Fang making a dangerous charge, but none of the eligible fighters are seriously wounded. The captain's badge remains with the wolf."}},"E117.5":{"s":"You do not interfere with the command of the orc patrol. Fang jumps off the box and leads the soldiers on the squirrel's trail."},"E118.1":{"s":"You hand over the gold for the captive before sunrise, and both families accept the deal. Having recovered, the soldier decides to serve in your squad.","v":{"rs":"You ransom a wounded soldier, but you cannot accept the soldier into the squad. He leaves gold in gratitude for his salvation."}},"E118.2":{"s":"You remind both families that the guest has not yet had time to tell his story. They extend protection and give you supplies for mediation.","f":"The families accuse the party of breaking custom and begin to argue with weapons in their hands. A skirmish begins."},"E118.3":{"s":"You leave the dispute to two orc families. There is very little time left before dawn, and the soldier is still lying by the fire."},"E118.4":{"s":"The soldier, having gathered his last strength, chooses to serve the King instead of indefinite captivity. The families allow him to leave with the party.","f":"The soldier cannot give a meaningful answer, and the families refuse to make an agreement for him. The squad does not receive a new fighter.","v":{"rs":"The soldier chooses a service, but it is impossible to accept him into the detachment. He thanks for the choice offered in gold."}},"E118.5":{"s":"After strict demands, the families agree to release the captive for monetary compensation. The squad receives gold, although the orcs see it off with hostility.","f":"The orcs reject the claim to the prisoner as a thing and call fighters from both clans. The battle begins."},"E119.1":{"s":"The king signs the transfer of the flight to the nearest cemetery, and Rem finally puts away the watch. From the luggage of long-vanished passengers, he allocates supplies to the detachment."},"E119.2":{"s":"You close the flight with the royal signature, and the passengers silently leave the stagecoach. Rem hands you an old cash register with gold.","f":"Rehm declares the closure of the flight a violation of obligations to passengers. Armed dead men emerge from the carriage and a skirmish begins."},"E119.3":{"s":"Rem takes the statement out of the box and pays the accumulated road tax in gold. His watch finally stops ticking.","f":"The demand for a tax for one hundred and forty-two years angers all twelve passengers. They rise from the carriage with weapons - the battle begins."},"E119.4":{"s":"You refuse to sign someone else's document with unknown ink. Rem sighs heavily, checks his watch and continues to wait for the next monarch."},"E120.1":{"s":"You don’t touch the old shoes and allow Agna’s family to sit quietly until dawn. The hostess gives food for the journey in gratitude."},"E120.2":{"s":"Agna explains to whom the fourth bowl was prepared, and as a sign of trust she takes out an old purse of gold. Dead people don't interfere in conversation.","f":"Agna takes the question as an attempt to break a family custom, and the dead rise from the table. A skirmish begins."},"E120.3":{"s":"{{heroName}} notices that the fourth bowl is not intended for the dead man, but for the guest whom Agna has been waiting for all these years. She gives gold and supplies for solving the mystery.","f":"{{heroName}} cannot connect the empty chair with Agna's family history. The hostess asks not to disturb the dead with questions."},"E120.4":{"s":"You lead the dead out of the house and find old coins in their abandoned equipment. Agna looks at the empty chairs without thanking you.","f":"Agna's husband and sons do not allow themselves to be driven out of the house, and other dead people gather outside. The battle begins."},"E120.5":{"s":"You leave before the night guests arrive at the house. Three pairs of old boots and one empty bowl remain at the threshold."},"E121.1":{"s":"The king pays minor arrears from his treasury, and Rothmar crosses out several lines at once. The spirits make room in the queue, but the Duke's Bridge is still considered a debt."},"E121.2":{"s":"You collect the remaining coins from the debtors and close some of the entries in Rothmar’s books. The gold goes to the squad.","f":"One of the ghosts declares the collection illegal, and the rest of the debtors raise an indignation. The cemetery line turns into a skirmish."},"E121.3":{"s":"{{heroName}} finds counter debts in the books and balances the balance without an imaginary bridge. Rothmar thanks with gold and supplies, putting down his pen for the first time.","f":"{{heroName}} reveals another unclosed line: the Duke's seven chickens have already been written off, but the bridge should still exist. Rothmar continues to count."},"E121.4":{"s":"You redeem the debt book for gold, and Rothmar solemnly formalizes the transfer of claims. The dead look at the new creditor with obvious disapproval."},"E121.5":{"s":"You leave the lich at his table among the eager spirits. He then asks to tell the Duke that the bridge is still needed."},"E122.1":{"s":"Ard pronounces the long-awaited oath, and Selena answers so quietly that only he can hear. The ghostly guests collect a golden wedding gift for the old man.","f":"Ard cannot complete the promise and retreats from the altar. Selena does not hold him back, but the wedding procession never disperses."},"E122.2":{"s":"Selena admits that waiting shouldn't take away the rest of Ard's life. Ghosts clear the road, and grateful travelers share supplies.","f":"The ghostly relatives consider your words an attempt to disrupt the wedding and stand between you and Ard. A skirmish begins."},"E122.3":{"s":"{{heroName}} completes the wedding ceremony as a memory of the promise made, without requiring Ard to pass on to the dead. The old man gives away the gold, and the guests leave supplies.","f":"{{heroName}} does not find a safe formula for an oath between the living and the dead. The ritual remains unfinished."},"E122.4":{"s":"You lead Ard out of the chapel before the ghostly procession can close the circle. He walks on his own, although he keeps looking back at Selena.","f":"Ghostly guests stand before the exit, preventing the groom from being taken away against his will. The battle begins."},"E122.5":{"s":"You leave Ard sitting across from Selene, not deciding for him. The ghostly procession waits patiently for the groom's first word."},"E123.1":{"s":"You suggest a new last song to Felen, and the cemetery audience finally demands a curtain. The artist gives gold as a thank-you offering.","f":"The dead are unhappy with the new ballad and demand another round of performances. To wait for a break, the squad wastes supplies."},"E123.2":{"s":"You pay Felen and take him away from the makeshift stage to the indignant whistling of the graves. The musician agrees to join the squad.","f":"As soon as the artist leaves his place, armed listeners emerge from their graves. A skirmish begins.","v":{"rs":"Felen is ready to leave with you, but he cannot accept a new fighter. For help, he hands over gold, remaining at the cemetery scene."}},"E123.3":{"s":"You take the lute from Felen and end the performance with such a song that even the lids of the coffins fall silent. From the coins left behind, the squad gets gold.","f":"The audience responds to the false note with a hail of bones, and {{affectedHeroName}} is seriously wounded.","v":{"nf":"The cemetery crowd showers the stage with bones, but none of the eligible combatants are seriously wounded. The concert continues without reward."}},"E123.4":{"s":"You strip the stage down to the last board, depriving the dead of a reason to demand more songs. Fehlen is finally able to step out of the gate.","f":"The cemetery audience rebels against the cancellation of the performance and emerges from their graves with weapons. The battle begins."},"E123.5":{"s":"You finish listening to the ballad and leave amidst satisfied applause. Felen discreetly passes you travel food while the spectators are busy."},"E124.1":{"s":"You take a position at the bridge, and the refugees thank you with gold and supplies even before the battle. The creatures are already approaching from the gorge - the battle begins."},"E124.2":{"s":"While the skeleton holds the bridge, you lead the caravan along a hidden path. Refugees share rescued supplies.","f":"Creatures from the gorge notice the movement of the caravan and cut off the party's escape route. A skirmish begins."},"E124.3":{"s":"You suggest that the skeleton change his position at the bridge to a place next to the King. The guard accepts his new assignment and joins the squad.","f":"The guard replies that he will not leave his post until the living have gone to safety. The squad does not receive a new ally.","v":{"rs":"The guard accepts the offer to change his post, but it is impossible to include a new fighter in the squad. Refugees leave you gold as a thank you for trying to help."}},"E124.4":{"s":"You free the old guard from his endless guard oath. Gold is found in the abandoned armor.","f":"An attempt to remove the oath opens the way for creatures from the gorge. The squad has to join the battle."},"E124.5":{"s":"You choose to bypass the pass and spend extra supplies on the long journey. The skeleton remains on the bridge in front of the caravan."},"E125.1":{"s":"Nerissa accepts eight coins and pulls back the edge of the web like a curtain. The spider silently checks to see if anyone is left behind."},"E125.2":{"s":"You find an error in Nerissa's calculations, and she is forced to give a few coins in your favor. The spider taps the sign with its paw, demanding that the price be corrected.","f":"Neriss records your objections as a paid complaint and collects additional gold. The spider moves its paw approvingly."},"E125.3":{"s":"{{heroName}} walks along the rocky ledge above the network and shows the others a safe way around. Supplies remain in the cache found along the way.","f":"A narrow ledge breaks off under the scout's feet, and {{affectedHeroName}} is seriously wounded.","v":{"nf":"The rock ledge crumbles, but none of the eligible fighters are seriously injured. A workaround cannot be found."}},"E125.4":{"s":"You cut the net, and among the things stuck in the threads you find gold. Neriss does not have time to set a new duty.","f":"The spider accepts the damage to the canvas as an unpaid service and releases armed defenders. A skirmish begins."},"E125.5":{"s":"You turn your squad around in front of the web and leave the same way. Neriss writes another failed payer into the book."},"E126.1":{"s":"You confirm Vessara's refusal of the false order with your signature. The killer hands over the gold for testimony, and Olm breathes a sigh of relief."},"E126.2":{"s":"You find in the annex to the contract the name of the person who issued the order and the discrepancy between the seals. Vessara pays in gold for the discovered counterfeit.","f":"The appendix contains only the same legal formulas without new names. The customer cannot be identified."},"E126.3":{"s":"{{heroName}} asks Olm about the ring and finds a contradiction between his answers and the text of the order. Vessara gives gold for help in exposing.","f":"Olm answers cautiously and drags out the argument until darkness; supplies are spent waiting. {{heroName}} does not find sufficient evidence."},"E126.4":{"s":"You hand over the bound Olm to Vessara without further interrogation. She pays in gold, without promising that he will come out from under the aqueduct free."},"E126.5":{"s":"You disarm Vessara and hold Olm for trial. They find gold on them, which was given to the detachment as security for the proceedings.","f":"Vessara snatches the hidden dagger, and Olm breaks the bonds. An arrest attempt turns into a confrontation."},"E127.1":{"s":"Saer leads the party through the underground route, and his shadow is never far enough behind to block the path. On the way out, he shares his supplies.","f":"In a narrow passage, an alien shadow grabs {{affectedHeroName}} by the legs, leaving a serious wound.","v":{"nf":"A shadow falls on the squad, but none of the eligible fighters are seriously wounded. You have to leave the passage without paying."}},"E127.2":{"s":"You shine a bright light at Saeru's feet, and his shadow unsticks from the stone. The conductor thanks you in gold.","f":"The shadow does not disappear from the light, but rises from the floor as a separate armed figure. A skirmish begins."},"E127.3":{"s":"{{heroName}} determines that the shadow is attached to the old road mark, and not to Saer. For clarification, the guide gives away supplies.","f":"{{heroName}} does not find a reliable trace of magic, but attempts to check the shadow consume supplies. Saer remains with the same question."},"E127.4":{"s":"You address the shadow as a separate being, and it responds with a condition: gold for the right to leave Saer alone. The contract brings payment to the detachment.","f":"The Shadow refuses to talk to people, separates from Saer and calls for the creatures of the underground path. The battle begins."},"E127.5":{"s":"You refuse a guide whose shadow walks according to its own rules. Saer silently goes into the underground path, and the shadow lingers for one step."},"E128.1":{"s":"You acknowledge Sita's win and use up the supplies to help lift the load up the stone wall. Kel thanks with gold, and the spider triumphantly taps her paws."},"E128.2":{"s":"You replace the filed dice with honest ones, and a new roll resolves the dispute without cheating. Kael pays gold for the restored rules.","f":"Sita refuses to acknowledge the replay until Kael pays her a penalty. For an attempt to reconcile the disputants, gold is withheld from the detachment."},"E128.3":{"s":"{{heroName}} holds a fair competition on an accessible route, and Kel and Sita recognize the new result. For judging, the squad gets gold.","f":"On a steep descent, {{affectedHeroName}} is seriously injured when Sita suddenly changes direction.","v":{"nf":"At a dangerous turn, the race stops, but none of the eligible fighters are seriously injured. There is no judge's award."}},"E128.4":{"s":"You give gold for sawed bones and hide them as evidence of deception. Sita sees off the purchase with three dissatisfied blows of her paw."},"E128.5":{"s":"You leave Kel and Sita to figure out the terms of the old bet. The spider is already transferring the saddle to the vertical wall."},"E129.1":{"s":"The eldest heir touches the obsidian and sees the last strong memory left by the prince. The family gives the squad gold for performing the ceremony.","f":"The slab shows only a vague image without a face, and the touch erases the previous trace. The heirs start arguing again."},"E129.2":{"s":"The king touches the obsidian, and a memory of the prince's last day appears on the surface. The family pays in gold for what they see.","f":"Someone else's memory burns the King from the inside, leaving a serious wound. The image of the prince fades.","v":{"nf":"Obsidian responds with a painful splash, but the King is not seriously wounded. The memory still cannot be read."}},"E129.3":{"s":"{{heroName}} compares the answers of the four heirs and finds the one who is hiding his meeting with the prince. The family pays for the conclusions in gold, without touching the stove.","f":"{{heroName}} reveals too many contradictions to name one culprit. They decide to save their only attempt for now."},"E129.4":{"s":"You seal the obsidian, preventing any heir from erasing someone else's memory. Eshra thanks the party for the travel supplies they left behind."},"E129.5":{"s":"You sell the right to touch the slab to the most generous heir and receive gold. The rest are forced to accept the deal.","f":"Rivals accuse the winning bidder of bribery and draw their weapons right at the stove. The battle begins."},"E130.1":{"s":"You pay for Lian’s travel to the doctors, and for the first time she takes from the shelf not the family hood, but her own bag. Meret silently pours her tea."},"E130.2":{"s":"You support Meret's demand for inheritance of the craft. The executioner thanks him with gold, and Lian puts the unfinished cup on the table."},"E130.3":{"s":"You offer Lian to study healing without completely breaking the family tradition of knowledge of the human body. Meret pays in gold and adds supplies to the road.","f":"Lian replies that she wants to treat the living, and not look for a beautiful name for an old profession. The conversation ends without agreement."},"E130.4":{"s":"Lian collects a dressing kit and decides to start practicing on your hike. Meret reluctantly blesses her at the door.","f":"Meret does not allow her daughter to go to an unfamiliar detachment, and Lian remains at home. You don't get a new companion.","v":{"rs":"Lian is ready to go with you, but she cannot accept a new fighter. She gives the squad gold and remains to prepare for training."}},"E130.5":{"s":"You finish your tea and do not interfere in Meret’s argument with Lian. Before leaving, the girl quietly puts some travel supplies for you."},"E131.1":{"s":"The staircase groans but holds; a new gear soon brings the lift back to life. Dorn counts out your reward as voices cheer from the cage: “The beer is saved!”","f":"The rotten steps tear loose from their fastenings on the way back. {{affectedHeroName}} manages to warn the others but suffers a grave wound.","v":{"nf":"The emergency stairs crumble, but none of the eligible fighters suffers a grave wound. You must leave the gear on the lower floor."}},"E131.2":{"s":"The squad pulls the chains until their fingers go numb, and the cage finally rises to the edge of the shaft. The rescued miners share their supplies, although they refuse to part with the barrel.","f":"The chain jerks out of your hands, and the cage remains hanging over the void. Another part of the supplies is spent on fruitless attempts."},"E131.3":{"s":"{{heroName}} ties the trolleys with chains and assembles a mechanism that Dorn only laughed at at first. When a square is climbed to the top, the miners pay in gold and share provisions.","f":"The chain tightens, the trolleys grind - and the entire transmission crumbles before Dorn's eyes. {{heroName}} angrily asks not to call it a lift anymore."},"E131.4":{"s":"The cage falls down, but the lower brake catches it with a roar an instant before impact. The miners emerge into the light and pay generously for salvation.","f":"The cable breaks before the signal and the brake fails. Screams from the mine force the squad to draw their weapons: a battle is ahead."},"E131.5":{"s":"You leave Dorn and his comrades to deal with the breakdown. From the depths of the mine they shout after you that the barrel is still full."},"E132.1":{"s":"Brun and Keld argue over each work until the notary Mara announces the result of the competition. The winner gives you the promised payment, and the loser demands revenge.","f":"Brothers quarrel even before the first blow of the hammer; the competition has to be cancelled. While you move them to different corners, part of the provisions is consumed."},"E132.2":{"s":"A second anvil is installed in the forge, and the brothers fall silent for the first time all day. For a peaceful solution, they give you supplies.","f":"The first argument about who will get the forge ends in a fight. Instead of dividing up the inheritance, a skirmish awaits you."},"E132.3":{"s":"{{heroName}} draws the brothers' attention to the words of their late father, and not to the controversial forge. Mara recognizes the decision as fair and gives a reward.","f":"{{heroName}} finds a new clue, but the brothers immediately interpret it each in their own favor. The will remains a subject of dispute."},"E132.4":{"s":"You buy back the forge from the brothers by paying the required amount. Notary Mara hastily notarizes the contract before Brun and Keld change their minds."},"E132.5":{"s":"You refuse to interpret the cryptic words of the late dwarf. Mara sighs, and the brothers immediately demand that they at least toss a coin."},"E133.1":{"s":"“Malyutka” rumbles so much that the crew’s ears are ringing; The snow wall finally disappears into the gorge. The grateful dwarves provide you with supplies.","f":"The shot removes only a measly handful of snow from the slope. Frida thoughtfully asks for the fourth version of the calculations."},"E133.2":{"s":"Instead of taking a risky shot, the detachment takes up shovels and opens the passage by evening. Dwarves pay in gold for hard but reliable work."},"E133.3":{"s":"{{heroName}} finds an error in the calculations and orders the charges to be rearranged. The avalanche goes where it needs to go, and the Malyutka’s crew thanks you with coins and supplies.","f":"Even corrected calculations do not save the situation: snow remains on the road. For the first time that day, Frida does not argue with {{heroName}}."},"E133.4":{"s":"You pay for one more shell for the “Malyutka”. Frida solemnly promises that this time the calculations will certainly coincide."},"E133.5":{"s":"The squad leaves to look for another pass, leaving Frieda with a cannon the size of a house. The long walk eats up some of the supplies."},"E134.1":{"s":"The royal decree is read out in front of the barrel with such solemnity that the rune finally disappears. Hulda triumphantly distributes the contents, and the party receives supplies.","f":"The barrel listens to the decree and displays a new inscription on the lid: “DON’T CONVINCE.” Halda states that she now hates public holidays."},"E134.2":{"s":"After the third blow, the lid finally gives in, and the brewery explodes with a triumphant roar. Khalda pours water for everyone and gives some of the supplies for the journey.","f":"The hammer breaks on the lid, and the rune reads: “ATTEST COUNTED, GREATNESS NOT.” Hulda asks you not to encourage the barrel anymore."},"E134.3":{"s":"{{heroName}} deciphers the old rune and pronounces the condition that Halda’s grandfather chose to remain silent about. The barrel is opened, and the brewery thanks the party with gold and supplies.","f":"{{heroName}} reads the rune, but it immediately rearranges itself and demands an even greater feat. Hulda, in desperation, calls for the next interpreter."},"E134.4":{"s":"A collector buys an unopened barrel solely for the \"NOT BIGGEST ENOUGH\" label. Halda shares gold with you for good advice.","f":"The collector demands proof that the beer exists at all, but the barrel refuses to provide it. The deal falls through."},"E134.5":{"s":"You leave the barrel waiting for a truly great occasion; Khalda gives you provisions for the journey. The word \"PATIENCE\" appears on the lid."},"E135.1":{"s":"Tob pulls up the padded barrier and Rinna finally stops without smashing the car to pieces. The mechanic pays you in gold.","f":"Rinna flies through the barricade, scattering bags across the road. We have to spend new supplies to clean up the wreckage."},"E135.2":{"s":"You cling to the motorcycle at full speed and reach for the emergency lever. Rinna stops and Tob, the mechanic, hands over the award with trembling hands.","f":"The wheels go out from under your feet before you can grab the saddle. {{affectedHeroName}} remains on the road with a serious injury.","v":{"nf":"The motorcycle eludes the interceptor, but none of the available fighters are seriously injured. Rinna continues her dangerous journey."}},"E135.3":{"s":"{{heroName}} leads Rinna up a long slope until the movement rune loses its power. Tob hands the party gold and supplies.","f":"The rune only flares up with each new rise, and Rinna disappears again over the horizon. {{heroName}} admits that the car turned out to be more stubborn."},"E135.4":{"s":"Tob hits the power source, and the motorcycle freezes at the edge of the road with a final roar. The mechanic pays for the rescue in gold.","f":"The shot damages the protective rune, and sentry machine guns emerge from the broken circuit. A skirmish begins."},"E135.5":{"s":"You step back to the side of the road as Rinna speeds past for the fourth time. Tob shouts after him that “the system is theoretically reliable.”"},"E136.1":{"s":"Okko turns off the blocking, and the Tit takes off above the trees, trembling with fear and wind. The pilot thanks you in gold.","f":"\"Tit\" begins to take off, then lands sharply and demands to check the engine; Repeated testing consumes supplies."},"E136.2":{"s":"Okko agrees to take off his wings and leave the Titmouse to ride on the ground. He pays for unusual but working advice in gold.","f":"“Tit” refuses to be a cart with a propeller, and Okko again takes up the flight instructions. There is no buyer."},"E136.3":{"s":"{{heroName}} offers a series of short jumps, and the Tit gradually gets used to not touching the ground. Okko rejoices so loudly that he pays with both gold and supplies.","f":"Even on the palm of your hand above the grass, “Tit” turns off the engine and sits back down. {{heroName}} decides not to torment the frightened car."},"E136.4":{"s":"Okko sits next to you at the helm, and the Tit finally flies over the meadow without falling back. The pilot pays in gold for the best flight of his life.","f":"On the first climb, the “Tit” abruptly stops the propeller; {{affectedHeroName}} seriously injured during a hard landing.","v":{"nf":"\"Tit\" disrupts the first ascent, but none of the available fighters is seriously wounded. Okko decides not to try again."}},"E136.5":{"s":"You leave Okko and \"Tit\" to deal with their fear of heights without royal input. In the meadow the cautious whirring of the propeller is heard again."},"E137.1":{"s":"Fuzz hands over the paid supplies and points to the signature on page forty-seven. This time the contract was truly fulfilled.","f":"On page forty-six there is a clause about fees for storing supplies. After the deal, there are fewer of them left than the squad expected."},"E137.2":{"s":"The demon happily inscribes a new bridge in his honor and lays out gold for the right to own the name. He does not ask where the bridge itself is located.","f":"Fuzz finds a clause in the contract to verify the existence of the bridge and collects a penalty. Part of the treasury is spent on legal surprises."},"E137.3":{"s":"{{heroName}} finds in the attachment the buyer's right to terminate the contract on any forty-eighth page. Fuzz pays in gold to keep the dispute from going to court.","f":"{{heroName}} checks each line, but Fuzz even included the right to check the right to check. The demon politely offers a new contract."},"E137.4":{"s":"The king signs a gigantic treaty, and Fuzz counts out an impressive amount in gold. The last pages remain suspiciously warm.","f":"The agreement is sealed with a black seal, and {{affectedHeroName}} is seriously injured. Fuzz apologizes for the \"standard condition\".","v":{"nf":"The black seal of the treaty flashes beneath the king's signature, but none of the available fighters are seriously wounded. Fuzz hides the last pages."}},"E137.5":{"s":"You leave without wanting to read the door-sized contract. Demon Fuzz then offers a free consultation on forty-seven sheets."},"E138.1":{"s":"Three heads simultaneously rush behind the stick, clearing the way. Huntsman Khar looks at you with genuine horror, but the passage remains open.","f":"The dog returns the stick before you can pass and again blocks the path. Khar shouts that he warned."},"E138.2":{"s":"Khar accepts the gold and holds the dog by all three collars. The squad passes by while the monster's tail knocks down another road sign."},"E138.3":{"s":"{{heroName}} attracts the dog with a game to a safe clearing, and he forgets about the road. Khar gives out gold and some supplies.","f":"The dog grabs the stick along with the glove, and {{affectedHeroName}} is seriously wounded. Khar rushes to separate his pet.","v":{"nf":"The hellhound grabs the stick and glove, but none of the available fighters are seriously wounded. Khar stops playing."}},"E138.4":{"s":"Khar throws you the gold he promised for eliminating the obstacle, but the dog has already opened all three mouths. The battle begins."},"E138.5":{"s":"The detachment climbs the scree above the charred road, losing some of its supplies. Below you can still hear the joyful barking of three heads at once."},"E139.1":{"s":"Ishra weighs the black coin on her claw and pays gold for the rare item. Mira turns away before he can name her price."},"E139.2":{"s":"The coin splits into two black halves, and Mira calmly exhales for the first time. For help, she shares supplies.","f":"At the first strike, the coin calls the demon Ishra to arms; he does not want to lose his find. A skirmish breaks out."},"E139.3":{"s":"{{heroName}} removes the curse without destroying the memory of the deed. Mira thanks you with gold and supplies, without hiding her gaze for the first time.","f":"{{heroName}} notices that the coin only redirects the curse when trying to cleanse it. The ritual is stopped without risking someone else's memory."},"E139.4":{"s":"The coin falls into your palm like an icy spot; with it you receive gold, but someone else’s guilt cannot be shaken off in one move.","f":"The coin burns the one who decided to take it, and {{affectedHeroName}} is seriously injured. Ishra silently puts her hands behind her back.","v":{"nf":"Someone else's coin burns the one who took it, but none of the available fighters is seriously injured. Ishra asks to leave the find on the road."}},"E139.5":{"s":"You walk away from the fire, where Ishra and Mira are still looking at the black coin. None of them are trying to detain you."},"E140.1":{"s":"Both living visitors find their own dates of birth in the lists and prove that they are not yet dead. Ulf gives you supplies as \"official compensation\".","f":"The registrar requires a certificate that the living are truly alive, issued after death. To get people out of line, you have to spend gold."},"E140.2":{"s":"Ulf charges a fee for urgent service and unexpectedly returns part of the money to you as official compensation. The queue moves two steps."},"E140.3":{"s":"The royal order forces Ulf to close the illegal portal and issue a fine in gold. The ghosts demand that the decision be signed retroactively.","f":"Ulf calls the guards of the afterlife archive to protect the active queue. A skirmish begins."},"E140.4":{"s":"You reach the window and suddenly receive gold as “compensation for erroneous registration.” Ulf immediately closes the reception for lunch.","f":"Ulf issues a ticket with a number that no one in this line has ever seen. The squad leaves with nothing."},"E140.5":{"s":"You skirt the line so wide that the last ghost doesn't even notice you. Ulf then announces a new column: “Left without filing an application.”"},"E141.1":{"s":"Tsarr hands over a free ampoule and writes the King into the buyers' register. No one has yet vouched for the seven minutes of its action.","f":"The glass ampoule cracks even at the counter, and part of the camp supplies goes to cleaning up the caustic mixture. Tsarr reminds us that advertising cannot be returned."},"E141.2":{"s":"You count out thirty gold pieces, and Tsarr puts two more ampoules into the case. He specifically warns that minutes cannot be added to each other."},"E141.3":{"s":"{{heroName}} notices a strange condition in the magazine: seven minutes does not add life, but only postpones the consequences. Tsarr pays with supplies for an accurate check.","f":"{{heroName}} cannot disassemble the composition without opening the ampoule, and Tsarr refuses to donate the goods. The verification remains incomplete."},"E141.4":{"s":"The subject drinks the contents and passes the test without noticeable harm. Tsarr pays the promised gold for the demonstration.","f":"When the mixture wears off, {{affectedHeroName}} is seriously injured. Tsarr hastily slams the review journal shut.","v":{"nf":"The ampoule produces a dangerous reaction, but none of the eligible fighters are seriously injured. Tsarr does not pay rewards."}},"E141.5":{"s":"You break the ampoules before Tsarr can hide them. They manage to take gold from his counter to pay for dangerous goods.","f":"Tsarr is calling for armed buyers who don't like the destruction of their future immortality. The battle begins."},"E142.1":{"s":"The king signs the statement, and the mirror goes silent for the first time. Grisk decides not to return to the legion and joins the detachment.","f":"The executors of the boss's orders jump out of the mirror and demand that Grisk be returned to duty. A skirmish begins.","v":{"rs":"The application is signed, but Grisk cannot join the squad. He thanks him for his dismissal with gold and goes his way."}},"E142.2":{"s":"Grisk lays out the gold for the royal signature faster than the boss can object from the mirror. The certificate has been issued.","f":"The boss from the mirror states that paying a witness will nullify the independence of the signature. Grisk is left with an unsigned statement."},"E142.3":{"s":"You advise Grisk to simply not show up to the boss, and for the first time in a century he smiles. In gratitude, he leaves supplies.","f":"Grisk shows the clause in the agreement about punishment for absenteeism and takes up the application again. The advice was not enough."},"E142.4":{"s":"You refuse Grisk and return her mirror to the boss via a messenger. In return comes gold for maintaining legionary order."},"E142.5":{"s":"The mirror splits, and the boss's voice disappears along with the seal of submission. Grisk recognizes himself as free and joins the squad.","f":"A retaliatory blow breaks out from the fragments of the mirror, and {{affectedHeroName}} is seriously wounded. Grisk is still bound by his service.","v":{"rs":"The connection with the legion has been severed, but Grisk cannot join the detachment. For liberation he hands over gold.","nf":"The mirror fragments fly apart, but none of the eligible fighters are seriously injured. Grisk's statement remains in force under the old agreement."}},"E143.1":{"s":"You give the residents two shares of provisions and help raise the charred beams. Eiren remains nearby, without taking off his dirty gloves."},"E143.2":{"s":"You convince Eiren to continue the pursuit, promising to pass on help to the village. The angel leaves gold for the fire victims and the squad.","f":"Eiren refuses to leave and asks not to turn someone else's misfortune into a dispute over orders. Supplies are being sent to help residents."},"E143.3":{"s":"You send scouts on the trail of demons and return valuables found from enemies. The gold goes to the squad while Eiren helps the village.","f":"The reconnaissance encounters an armed demonic patrol before they can return. A skirmish begins."},"E143.4":{"s":"Eiren accepts the King's offer, hoping to find support for the affected village. Angel joins the squad.","f":"Eiren thanks for the invitation, but cannot leave the fire victims even for a while. He continues to clear the rubble.","v":{"rs":"Eiren is ready to join, but it is impossible to take a new fighter. He donates the gold for further assistance and remains with the village."}},"E143.5":{"s":"You leave Eiren among the charred walls. The angel picks up another beam along with those whom he recently protected."},"E144.1":{"s":"You help Sael remove the shining rings from the counter, and the trade stops. The angel pays gold for assistance.","f":"Pel declares the confiscation a robbery and calls for armed assistants. A skirmish begins."},"E144.2":{"s":"You count the fee and receive one shining ring with the condition “return at the request of heaven.” Pel hastily hides the proceeds.","f":"Before the purchase is completed, Sael demands the ring back and stops the deal. The gold has already gone to Pelu and is not coming back."},"E144.3":{"s":"{{heroName}} secures the rings to the ground while Sael takes them off the counter. For help, the angel gives gold and supplies.","f":"{{heroName}} discovers that the rings cannot be held without risk to the merchant. Confiscation has to be stopped."},"E144.4":{"s":"You accept Pel's argument about the lease, and the merchant pays to support his cause. Sael demands to see at least one contract signed by an angel.","f":"Pel cannot produce the lease agreement and falls silent under Sael's gaze. You do not receive gold for support."},"E144.5":{"s":"You move away from the counter before Pela is lifted off the ground completely. Sael is still arguing with him about ownership."},"E145.1":{"s":"You ask questions one at a time and discover whose silence makes the bell ring. Ophira pays for the solved riddle in gold.","f":"The pilgrims answer without contradiction, but the silver bell continues to ring for unspoken questions. The investigation is not progressing."},"E145.2":{"s":"The pilgrims write down their answers, and for the first time the bell does not interrupt them. According to the records, Ofira finds the cause of the alarm and gives out the gold.","f":"The bell rings even over empty sheets; The long search for an explanation consumes supplies. The notes don't clarify anything."},"E145.3":{"s":"{{heroName}} discovers that the ritual responds to the intention to hide the truth, even before the words are spoken. Ophira thanks for the corrected interpretation of gold.","f":"{{heroName}} checks the fastening and inscriptions, but the ritual itself cannot be understood. The bell continues to ring without answer."},"E145.4":{"s":"You remove the silver bell from its mounting, and its ringing stops. Ophira looks at the empty crossbar, not daring to stop you.","f":"An attempt to remove the shrine summons the heavenly guard. Armed defenders emerge from the side passages of the chapel and the battle begins."},"E145.5":{"s":"You leave Ophira and the pilgrims alone with the bell. A silver ringing accompanies the detachment to the road."},"E146.1":{"s":"You redeem the pawned wing, and Welt removes it from the register. Nira carefully takes the feathers back while the moneylender hides the gold."},"E146.2":{"s":"You demand to see permission to trade in angel wings, and Welt relents, paying gold for the refusal of claims.","f":"Welt presents the signed contract and issues an invoice for false accusations. The squad has to part with the gold."},"E146.3":{"s":"{{heroName}} finds a violation in the contract: the wing cannot be alienated as a whole thing together with the debtor. Welt pays gold to settle the dispute.","f":"{{heroName}} finds no reason to cancel yesterday’s deadline, and Nira remains in front of the pawnshop bars. The dispute continues."},"E146.4":{"s":"You pay part of the debt, and Nira agrees to serve in the unit until her obligation is paid off.","f":"Nira does not accept service as payment for the freedom of her own wing. The contributed gold remains with Welt; there is no new ally.","v":{"rs":"Nira accepts the agreement, but there is no room for a new fighter. She transfers gold instead of service, and the paid part of the debt is not returned."}},"E146.5":{"s":"You leave Nira at the pawnshop, and Velt to settle accounts with the future buyer of the wing. Nobody disputes the deal."},"E147.1":{"s":"You walk backwards for a mile and notice an old trail with a forgotten wallet and supplies. Amaron thanks for the company.","f":"Following Amaron's advice, the party goes astray and uses up supplies to return. The angel asks you to look at your feet more often."},"E147.2":{"s":"Amaron blesses the party's path and gives them travel supplies instead of walking together. He himself continues to move backwards towards the horizon."},"E147.3":{"s":"You accompany Amaron at a normal pace, warning of rocks and turns. He thanks in gold for your care.","f":"Amaron refuses accompaniment, which deprives his test of meaning. You disperse without reward."},"E147.4":{"s":"Amaron agrees that he has already learned to see the road behind him, and for the first time in forty days he turns to face forward.","f":"Amaron replies that no one else has the right to put an end to his lesson. He continues to walk backwards."},"E147.5":{"s":"You leave Amaron to continue his strange pilgrimage. The bell on the staff rings around the corner."},"E148.1":{"s":"You confirm that a miraculous salvation does not cancel the previous sentence. Judge Sariel accepts the conclusion and gives gold for participation in the proceedings."},"E148.2":{"s":"You propose to replace the execution with mandatory service to the affected family, and both parties accept the terms. The court supplies the squad with supplies.","f":"The victim's relatives consider the pardon a denial of their loss and are calling on supporters. A fight breaks out in the courtroom."},"E148.3":{"s":"{{heroName}} separates Ben’s obligation to answer for the murder from the relatives’ desire for immediate reprisal. Sariel approves the decision and rewards the squad with gold.","f":"{{heroName}} proposes to consider punishment separately from the miracle, but the parties do not accept the general formulation. The court postpones the decision."},"E148.4":{"s":"Ben agrees to dangerous service under the King's command rather than await an uncertain trial. He joins the squad.","f":"Ben refuses to change the court order to military service and remains in front of Sariel. The squad leaves without a new fighter.","v":{"rs":"Ben accepts the offer to serve, but he fails to recruit a new fighter. The court allocates gold to the detachment instead of the concluded contract."}},"E148.5":{"s":"You refuse to decide the case instead of the angelic court. Sariel thanks him for his presence and returns to the silent Ben."},"E149.1":{"s":"You give Roar warm food and shelter as his breath gradually stops covering the ground with frost. Hessa thanks with gold."},"E149.2":{"s":"The magical flame warms Roar's scales, and he finally stops trembling. Hessa shares supplies with the party.","f":"The fire meets the cold crystal with a sharp surge, and {{affectedHeroName}} is seriously wounded.","v":{"nf":"The ice blast disrupts healing, but none of the eligible fighters are seriously injured. Roar remains by the fire."}},"E149.3":{"s":"{{heroName}} displays the opposite rune on the coals, and the blue crystal loses its power inside Roar. Hessa hands over gold and supplies.","f":"{{heroName}} cannot pick up the rune without risking Roar's condition. The squad stops the attempt without reward."},"E149.4":{"s":"Roar agrees to try out a new job - cooling cellars in the summer heat. A satisfied employer pays the squad in gold for the idea.","f":"Hessa rejects the idea of making a craft out of her son’s illness. Roar wraps himself tighter in his cloaks, and the conversation ends."},"E149.5":{"s":"You leave Roar by the huge fire. Hessa throws another log while her son complains about the cold."},"E150.1":{"s":"You convince Dven to officially release Cassar from his oath, and the dark scar on his scales lightens. The merchant thanks him in gold for the decision.","f":"Dwen refuses to sign the release for fear of losing the caravan's security. Kassar remains bound by the same word."},"E150.2":{"s":"You find a stone from the washed away road and declare it the last of the terms of the treaty. Dwen acknowledges the completion of the oath and hands over the supplies.","f":"Kassar does not mistake a random fragment for the real last stone, and the search drags on. Some of the supplies are wasted."},"E150.3":{"s":"{{heroName}} draws up a new oath so that the guard ends after the safe arrival of the caravan. Kassar pronounces it without pain, and Dwen pays in gold.","f":"{{heroName}} cannot find words that both would consider an honest fulfillment of the old promise. The scar on Cassar's chest remains dark."},"E150.4":{"s":"You demand the literal fulfillment of the promise, and Kassar obediently returns to the wagon train. Dwen gives the squad gold, although the dark scar does not disappear."},"E150.5":{"s":"You leave the merchant and the ambassador to argue about the last stone of the disappeared road. Cassar looks at the scar again as Dwen unfolds the map."}});
export { OUTCOMES_EN_E101_E150 };
